s/buttons';\n@use 'components/cards';\n@use 'components/forms';\n@use 'sections/hero';\n@use 'sections/features';\n@use 'sections/testimonials';\n@use 'sections/contact';\n@use 'sections/footer';\n@use 'utilities/animations';\n@use 'utilities/responsive';\n\n// Import Google Fonts\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');\n\n// CSS Variables (Custom Properties)\n:root {\n    --primary-color: #f9a743;\n    --primary-gradient: linear-gradient(135deg, #f9a743 0%, #ffc947 100%);\n    --glass-bg: rgba(255, 255, 255, 0.25);\n    --glass-border: rgba(255, 255, 255, 0.18);\n    --shadow-soft: 0 8px 32px rgba(31, 38, 135, 0.37);\n    --shadow-glow: 0 0 40px rgba(249, 167, 68, 0.4);\n    --text-primary: #3c2f38;\n    --text-secondary: #7f8c8d;\n\n    // Stakco Brand Gradients - Light\n    --stakco-light-golden-sunrise: linear-gradient(135deg, #F9EA59 0%, #DFAC6D 100%);\n    --stakco-light-warm-rose-glow: linear-gradient(135deg, #F9EA59 0%, #B83267 100%);\n    --stakco-light-champagne-horizon: linear-gradient(135deg, #DFAC6D 0%, #D4984F 100%);\n    --stakco-light-golden-berry: linear-gradient(135deg, #F9EA59 0%, #D4984F 50%, #B83267 100%);\n\n    // Stakco Brand Gradients - Dark\n    --stakco-dark-velvet-night: linear-gradient(135deg, #3C2F38 0%, #B83267 100%);\n    --stakco-dark-deep-rosewood: linear-gradient(135deg, #3C2F38 0%, #D4984F 100%);\n    --stakco-dark-royal-twilight: linear-gradient(135deg, #3C2F38 0%, #DFAC6D 100%);\n    --stakco-dark-wine-gold: linear-gradient(135deg, #3C2F38 0%, #B83267 40%, #DFAC6D 100%);\n}\n\n// Import partials\n// @import 'base/reset';\n// @import 'base/typography';\n// @import 'components/cursor';\n// @import 'components/navigation';\n// @import 'components/buttons';\n// @import 'components/cards';\n// @import 'components/forms';\n// @import 'sections/hero';\n// @import 'sections/features';\n// @import 'sections/testimonials';\n// @import 'sections/contact';\n// @import 'sections/footer';\n// @import 'utilities/animations';\n// @import 'utilities/responsive';\n\n","// Base reset and global styles\n* {\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\n\nbody {\n    font-family: 'Inter', sans-serif;\n    line-height: 1.6;\n    color: var(--text-primary);\n    overflow-x: hidden;\n    scroll-behavior: smooth;\n    cursor: none; // Custom cursor is handled separately\n}\n\nhtml {\n    scroll-behavior: smooth;\n}\n\n// Section spacing\nsection {\n    position: relative;\n    z-index: 10;\n}","@import url(\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap\");\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: \"Inter\", sans-serif;\n  line-height: 1.6;\n  color: var(--text-primary);\n  overflow-x: hidden;\n  scroll-behavior: smooth;\n  cursor: none;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nsection {\n  position: relative;\n  z-index: 10;\n}\n\nh1, h2, h3, h4, h5, h6 {\n  font-weight: 600;\n  line-height: 1.2;\n}\n\n.text-primary {\n  color: var(--text-primary) !important;\n}\n\n.text-secondary {\n  color: var(--text-secondary) !important;\n}\n\n.text-white-50 {\n  color: rgba(255, 255, 255, 0.5) !important;\n}\n\n.gradient-text {\n  background: var(--primary-gradient);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  background-clip: text;\n}\n\n.cursor {\n  width: 20px;\n  height: 20px;\n  background: var(--primary-gradient);\n  border-radius: 50%;\n  position: fixed;\n  pointer-events: none;\n  z-index: 9999;\n  transition: transform 0.1s ease;\n  opacity: 0.8;\n}\n\n.cursor-follower {\n  width: 40px;\n  height: 40px;\n  border: 2px solid var(--primary-color);\n  border-radius: 50%;\n  position: fixed;\n  pointer-events: none;\n  z-index: 9998;\n  transition: all 0.3s ease;\n  opacity: 0.3;\n}\n\n.navbar {\n  transition: all 0.3s ease;\n  backdrop-filter: blur(20px);\n  -webkit-backdrop-filter: blur(20px);\n}\n.navbar.scrolled {\n  background: rgba(255, 255, 255, 0.95) !important;\n  box-shadow: 0 5px 30px rgba(0, 0, 0, 0.1);\n}\n\n.btn-modern {\n  background: var(--primary-gradient);\n  border: none;\n  border-radius: 50px;\n  padding: 15px 35px;\n  color: white;\n  font-weight: 600;\n  text-decoration: none;\n  display: inline-block;\n  transition: all 0.3s ease;\n  position: relative;\n  overflow: hidden;\n}\n.btn-modern::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: -100%;\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);\n  transition: left 0.5s;\n}\n.btn-modern:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 10px 25px rgba(249, 167, 68, 0.4);\n  color: white;\n}\n.btn-modern:hover::before {\n  left: 100%;\n}\n\n.glass-card {\n  background: var(--glass-bg);\n  backdrop-filter: blur(20px);\n  -webkit-backdrop-filter: blur(20px);\n  border-radius: 20px;\n  border: 1px solid var(--glass-border);\n  box-shadow: var(--shadow-soft);\n  padding: 2rem;\n  transition: all 0.3s ease;\n  position: relative;\n  z-index: 2;\n}\n.glass-card:hover {\n  transform: translateY(-10px);\n  box-shadow: var(--shadow-glow);\n}\n\n.whosfor-card {\n  background: white;\n  border-radius: 20px;\n  padding: 2rem;\n  height: 100%;\n  transition: all 0.3s ease;\n  border: 1px solid rgba(0, 0, 0, 0.05);\n  position: relative;\n  overflow: hidden;\n  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);\n}\n.whosfor-card::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 4px;\n  background: var(--primary-gradient);\n  transform: scaleX(0);\n  transition: transform 0.3s ease;\n}\n.whosfor-card:hover {\n  transform: translateY(-10px);\n  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);\n}\n.whosfor-card:hover::before {\n  transform: scaleX(1);\n}\n.whosfor-card:hover .whosfor-icon {\n  transform: rotate(360deg) scale(1.1);\n}\n\n.whosfor-icon {\n  width: 80px;\n  height: 80px;\n  background: var(--primary-gradient);\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin: 0 auto 1.5rem;\n  font-size: 2rem;\n  color: white;\n  transition: all 0.3s ease;\n}\n\n.feature-card {\n  background: white;\n  border-radius: 20px;\n  padding: 2rem;\n  height: 100%;\n  transition: all 0.3s ease;\n  border: 1px solid rgba(0, 0, 0, 0.05);\n  position: relative;\n  overflow: hidden;\n  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);\n}\n.feature-card::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 4px;\n  background: var(--primary-gradient);\n  transform: scaleX(0);\n  transition: transform 0.3s ease;\n}\n.feature-card:hover {\n  transform: translateY(-10px);\n  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);\n}\n.feature-card:hover::before {\n  transform: scaleX(1);\n}\n.feature-card:hover .feature-icon {\n  transform: rotate(360deg) scale(1.1);\n}\n\n.feature-icon {\n  width: 80px;\n  height: 80px;\n  background: var(--primary-gradient);\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin: 0 auto 1.5rem;\n  font-size: 2rem;\n  color: white;\n  transition: all 0.3s ease;\n}\n\n.testimonial-card {\n  background: var(--glass-bg);\n  backdrop-filter: blur(20px);\n  border-radius: 20px;\n  padding: 2rem;\n  border: 1px solid var(--glass-border);\n  height: 100%;\n  transition: all 0.3s ease;\n}\n.testimonial-card:hover {\n  transform: translateY(-10px);\n}\n\n.partner-card {\n  background: white;\n  border-radius: 15px;\n  padding: 2rem;\n  transition: all 0.3s ease;\n  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.05);\n}\n.partner-card:hover {\n  transform: translateY(-5px);\n  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.1);\n}\n.partner-card:hover .partner-logo img {\n  filter: grayscale(0%);\n}\n\n.partner-logo {\n  height: 60px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.partn