ooter-link-group li {\n  margin-bottom: 0.5rem;\n}\n.footer-link-group a {\n  color: rgba(255, 255, 255, 0.8);\n  text-decoration: none;\n  transition: all 0.3s ease;\n  font-size: 0.95rem;\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n.footer-link-group a:hover {\n  color: var(--primary-color);\n  transform: translateX(5px);\n}\n.footer-link-group a i {\n  font-size: 0.8rem;\n  opacity: 0.7;\n}\n\n.footer-social {\n  display: flex;\n  justify-content: center;\n  gap: 1rem;\n  margin-bottom: 2rem;\n}\n\n.social-link {\n  width: 45px;\n  height: 45px;\n  background: rgba(255, 255, 255, 0.1);\n  backdrop-filter: blur(10px);\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: white;\n  text-decoration: none;\n  transition: all 0.3s ease;\n  font-size: 1.1rem;\n}\n.social-link:hover {\n  background: var(--primary-gradient);\n  color: white;\n  transform: translateY(-3px);\n  box-shadow: 0 5px 15px rgba(249, 167, 67, 0.4);\n}\n\n.footer-bottom {\n  text-align: center;\n}\n\n.footer-bottom-content {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 1rem;\n}\n\n.footer-legal {\n  display: flex;\n  gap: 2rem;\n  align-items: center;\n  flex-wrap: wrap;\n}\n.footer-legal a {\n  color: rgba(255, 255, 255, 0.7);\n  text-decoration: none;\n  font-size: 0.9rem;\n  transition: all 0.3s ease;\n}\n.footer-legal a:hover {\n  color: var(--primary-color);\n}\n.footer-legal .separator {\n  color: rgba(255, 255, 255, 0.3);\n  font-size: 0.8rem;\n}\n\n.footer-copyright {\n  color: rgba(255, 255, 255, 0.6);\n  font-size: 0.85rem;\n  margin: 0;\n}\n\n.footer-patent {\n  background: rgba(249, 167, 67, 0.1);\n  border: 1px solid rgba(249, 167, 67, 0.2);\n  border-radius: 20px;\n  padding: 0.5rem 1rem;\n  font-size: 0.8rem;\n  color: var(--primary-color);\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  margin-top: 1rem;\n}\n\n@keyframes float {\n  0%, 100% {\n    transform: translateY(0px) rotate(0deg);\n  }\n  50% {\n    transform: translateY(-20px) rotate(5deg);\n  }\n}\n@keyframes rotateLayer1 {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}\n@keyframes rotateLayer2 {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}\n@keyframes rotateLayer3 {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}\n@keyframes rotate {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}\n@keyframes spin {\n  0% {\n    transform: rotate(0deg);\n  }\n  100% {\n    transform: rotate(360deg);\n  }\n}\n.loading-overlay {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: var(--text-primary);\n  z-index: 10000;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: opacity 0.5s ease;\n}\n\n.loading-spinner {\n  width: 60px;\n  height: 60px;\n  border: 4px solid rgba(249, 167, 68, 0.3);\n  border-top: 4px solid var(--primary-color);\n  border-radius: 50%;\n  animation: spin 1s linear infinite;\n}\n\n.fade-in {\n  opacity: 0;\n  transform: translateY(30px);\n  transition: all 0.8s ease;\n}\n.fade-in.visible {\n  opacity: 1;\n  transform: translateY(0);\n}\n\n.low-performance .floating-element {\n  animation: none;\n}\n.low-performance .puzzle-layer {\n  animation-duration: 20s;\n}\n\n@media (max-width: 768px) {\n  .hero-section h1 {\n    font-size: 2.5rem;\n  }\n  .feature-card,\n  .whosfor-card {\n    margin-bottom: 2rem;\n  }\n  .unique-features-section .row {\n    margin-bottom: 3rem;\n  }\n  .feature-content {\n    padding: 1rem 0;\n  }\n  .footer-content {\n    padding: 3rem 0 1.5rem;\n  }\n  .footer-links {\n    flex-direction: column;\n    gap: 2rem;\n    text-align: center;\n  }\n  .footer-bottom-content {\n    flex-direction: column;\n    text-align: center;\n  }\n  .footer-legal {\n    justify-content: center;\n    order: 2;\n  }\n  .footer-copyright {\n    order: 1;\n    margin-bottom: 1rem;\n  }\n}\n@media (max-width: 576px) {\n  .footer-links {\n    gap: 1.5rem;\n  }\n  .footer-legal {\n    flex-direction: column;\n    gap: 1rem;\n  }\n  .footer-legal .separator {\n    display: none;\n  }\n}\n@media (max-width: 768px) {\n  .display-5 {\n    font-size: 2rem;\n  }\n}\n\n@media (max-width: 768px) {\n  .display-6 {\n    font-size: 1.75rem;\n  }\n}\n\n@media (max-width: 768px) {\n  .lead {\n    font-size: 1rem;\n  }\n}\n\n:root {\n  --primary-color: #f9a743;\n  --primary-gradient: linear-gradient(135deg, #f9a743 0%, #ffc947 100%);\n  --glass-bg: rgba(255, 255, 255, 0.25);\n  --glass-border: rgba(255, 255, 255, 0.18);\n  --shadow-soft: 0 8px 32px rgba(31, 38, 135, 0.37);\n  --shadow-glow: 0 0 40px rgba(249, 167, 68, 0.4);\n  --text-primary: #3c2f38;\n  --text-secondary: #7f8c8d;\n  --stakco-light-golden-sunrise: linear-gradient(135deg, #F9EA59 0%, #DFAC6D 100%);\n  --stakco-light-warm-rose-glow: linear-gradient(135deg, #F9EA59 0%, #B83267 100%);\n  --stakco-light-champagne-horizon: linear-gradient(135deg, #DFAC6D 0%, #D4984F 100%);\n  --stakco-light-golden-berry: linear-gradient(135deg, #F9EA59 0%, #D4984F 50%, #B83267 100%);\n  --stakco-dark-velvet-night: linear-gradient(135deg, #3C2F38 0%, #B83267 100%);\n  --stakco-dark-deep-rosewood: linear-gradient(135deg, #3C2F38 0%, #D4984F 100%);\n  --stakco-dark-royal-twilight: linear-gradient(135deg, #3C2F38 0%, #DFAC6D 100%);\n  --stakco-dark-wine-gold: linear-gradient(135deg, #3C2F38 0%, #B83267 40%, #DFAC6D 100%);\n}","// Typography Base Styles\n\n// Base font settings are handled in the reset file\n// Additional typography utilities and overrides go here\n\nh1, h2, h3, h4, h5, h6 {\n    font-weight: 600;\n    line-height: 1.2;\n}\n\n.text-primary {\n    color: var(--text-primary) !important;\n}\n\n.text-secondary {\n    color: var(--text-secondary) !important;\n}\n\n// Text utilities for white text\n.text-white-50 {\n    color: rgba(255, 255, 255, 0.5) !important;\n}\n\n// Gradient text effect\n.gradient-text {\n    background: var(--primary-gradient);\n    -webkit-background-clip: text;\n    -webkit-text-fill-color: transparent;\n    background-clip: text;\n}","// Custom Cursor Styles\n.cursor {\n    width: 20px;\n    height: 20px;\n    background: var(--primary-gradient);\n    border-radius: 50%;\n    position: fixed;\n    pointer-events: none;\n    z-index: 9999;\n    transition: transform 0.1s ease;\n    opacity: 0.8;\n}\n\n.cursor-follower {\n    width: 40px;\n    height: 40px;\n    border: 2px solid var(--primary-color);\n    border-radius: 50%;\n    position: fixed;\n    pointer-events: none;\n    z-index: 9998;\n    transition: all 0.3s ease;\n    opacity: 0.3;\n}","// Navigation Styles\n.navbar {\n    transition: all 0.3s ease;\n    backdrop-filter: blur(20px);\n    -webkit-backdrop-filter: blur(20px);\n\n    &.scrolled {\n        background: rgba(255, 255, 255, 0.95) !important;\n        box-shadow: 0 5px 30px rgba(0, 0, 0, 0.1);\n    }\n}","// Button Styles\n.btn-modern {\n    background: var(--primary-gradient);\n    border: none;\n    border-radius: 50px;\n    padding: 15px 35px;\n    color: white;\n    font-weight: 600;\n    text-decoration: none;\n    display: inline-block;\n    transition: all 0.3s ease;\n    position: relative;\n    overflow: hidden;\n\n    &::before {\n        content: '';\n        position: absolute;\n        top: 0;\n        left: -100%;\n        width: 100%;\n        height: 100%;\n        background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);\n        transition: left 0.5s;\n    }\n\n    &:hover {\n        transform: translateY(-2px);\n        box-shadow: 0 10px 25px rgba(249, 167, 68, 0.4);\n        color: white;\n\n        &::before {\n            left: 100%;\n        }\n    }\n}","// Card Components\n.glass-card {\n    background: var(--glass-bg);\n    backdrop-filter: blur(20px);\n    -webkit-backdrop-filter: blur(20px);\n    border-radius: 20px;\n    border: 1px solid var(--glass-border);\n    box-shadow: var(--shadow-soft);\n    padding: 2rem;\n    transition: all 0.3s ease;\n    position: relative;\n    z-index: 2;\n\n    &:hover {\n        transform: translateY(-10px);\n        box-shadow: var(--shadow-glow);\n    }\n}\n\n// Who's For Cards\n.whosfor-card {\n    background: white;\n    border-radius: 20px;\n    padding: 2rem;\n    height: 100%;\n    transition: all 0.3s ease;\n    border: 1px solid rgba(0, 0, 0, 0.05);\n    position: relative;\n    overflow: hidden;\n    box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);\n\n    &::before {\n        content: '';\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 100%;\n        height: 4px;\n        background: var(--primary-gradient);\n        transform: scaleX(0);\n        transition: transform 0.3s ease;\n    }\n\n    &:hover {\n        transform: translateY(-10px);\n        box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);\n\n        &::before {\n            transform: scaleX(1);\n        }\n\n        .whosfor-icon {\n            transform: rotate(360deg) scale(1.1);\n        }\n    }\n}\n\n.whosfor-icon {\n    width: 80px;\n    height: 80px;\n    background: var(--primary-gradient);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    margin: 0 auto 1.5rem;\n    font-size: 2rem;\n    color: white;\n    transition: all 0.3s ease;\n}\n\n// Feature Cards\n.feature-card {\n    background: white;\n    border-radius: 20px;\n    padding: 2rem;\n    height: 100%;\n    transition: all 0.3s ease;\n    border: 1px solid rgba(0, 0, 0, 0.05);\n    position: relative;\n    overflow: hidden;\n    box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);\n\n    &::before {\n        content: '';\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 100%;\n        height: 4px;\n        background: var(--primary-gradient);\n        transform: scaleX(0);\n        transition: transform 0.3s ease;\n    }\n\n    &:hover {\n        transform: translateY(-10px);\n        box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);\n\n        &::before {\n            transform: scaleX(1);\n        }\n\n        .feature-icon {\n            transform: rotate(360deg) scale(1.1);\n        }\n    }\n}\n\n.feature-icon {\n    width: 80px;\n    height: 80px;\n    background: var(--primary-gradient);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    margin: 0 auto 1.5rem;\n    font-size: 2rem;\n    color: white;\n    transition: all 0.3s ease;\n}\n\n// Testimonial Cards\n.testimonial-card {\n    background: var(--glass-bg);\n    backdrop-filter: blur(20px);\n    border-radius: 20px;\n    padding: 2rem;\n    border: 1px solid var(--glass-border);\n    height: 100%;\n    transition: all 0.3s ease;\n\n    &:hover {\n        transform: translateY(-10px);\n    }\n}\n\n// Partner Cards\n.partner-card {\n    background: white;\n    border-radius: 15px;\n    padding: 2rem;\n    transition: all 0.3s ease;\n    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.05);\n\n    &:hover {\n        transform: translateY(-5px);\n        box-shadow: 0 15px 30px rgba(0, 0, 0, 0.1);\n\n        .partner-logo img {\n            filter: grayscale(0%);\n        }\n    }\n}\n\n.partner-logo {\n    height: 60px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n\n    img {\n        max-height: 100%;\n        max-width: 100%;\n        object-fit: contain;\n        filter: grayscale(100%);\n        transition: filter 0.3s ease;\n    }\n}\n\n.partner-link {\n    text-decoration: none;\n    color: inherit;\n}\n\n// Enhanced card hover effects\n.card-hover-effect {\n    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n\n    &:hover {\n        transform: translateY(-8px) scale(1.02);\n        box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);\n    }\n}\n\n// Image Stack\n.image-stack {\n    position: relative;\n    display: inline-block;\n    width: 100%;\n    aspect-ratio: 1 / 1;\n    max-width: 100%;\n    margin: 0 auto;\n\n    .layer {\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 100%;\n        height: 100%;\n        transform-origin: center center;\n        animation-timing-function: ease-out;\n        animation-fill-mode: forwards;\n\n        &.layer-1 {\n            z-index: 1;\n            animation: rotate 4s ease-out forwards;\n        }\n\n        &.layer-2 {\n            z-index: 2;\n            animation: rotate 5s ease-out forwards;\n        }\n\n        &.layer-3 {\n            z-index: 3;\n            animation: rotate 6s ease-out forwards;\n        }\n    }\n}","// Form Styles\n.form-control {\n    background: rgba(255, 255, 255, 0.1);\n    border: 1px solid rgba(255, 255, 255, 0.2);\n    border-radius: 10px;\n    padding: 15px;\n    color: white;\n    margin-bottom: 1rem;\n    transition: all 0.3s ease;\n\n    &:focus {\n        background: rgba(255, 255, 255, 0.15);\n        border-color: var(--primary-color);\n        box-shadow: 0 0 0 0.2rem rgba(249, 167, 68, 0.25);\n        color: white;\n    }\n\n    &::placeholder {\n        color: rgba(255, 255, 255, 0.7);\n    }\n\n    // Validation states\n    &.is-invalid {\n        border-color: #dc3545;\n        box-shadow: 0 0 0 0.2rem rgba(220, 53, 69, 0.25);\n    }\n\n    &.is-valid {\n        border-color: var(--primary-color);\n        box-shadow: 0 0 0 0.2rem rgba(249, 167, 68, 0.25);\n    }\n}\n\n.invalid-feedback {\n    display: block;\n    width: 100%;\n    margin-top: 0.25rem;\n    font-size: 0.875em;\n    color: #dc3545;\n}\n\n// Alert styles\n.alert {\n    border-radius: 10px;\n    border: none;\n    font-weight: 500;\n\n    &.alert-success {\n        background: rgba(40, 167, 69, 0.1);\n        color: #28a745;\n        border: 1px solid rgba(40, 167, 69, 0.2);\n    }\n\n    &.alert-danger {\n        background: rgba(220, 53, 69, 0.1);\n        color: #dc3545;\n        border: 1px solid rgba(220, 53, 69, 0.2);\n    }\n}","// Hero Section Styles\n.hero-section {\n    min-height: 100vh;\n    background: var(--stakco-dark-wine-gold);\n    position: relative;\n    display: flex;\n    align-items: center;\n    overflow: hidden;\n    z-index: 1;\n\n    &::before {\n        content: '';\n        position: absolute;\n        top: 0;\n        left: 0;\n        right: 0;\n        bottom: 0;\n        background: url('data:image/svg+xml,<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\"><defs><pattern id=\"grain\" width=\"100\" height=\"100\" patternUnits=\"userSpaceOnUse\"><circle cx=\"25\" cy=\"25\" r=\"1\" fill=\"white\" opacity=\"0.1\"/><circle cx=\"75\" cy=\"75\" r=\"1\" fill=\"white\" opacity=\"0.1\"/><circle cx=\"50\" cy=\"10\" r=\"0.5\" fill=\"white\" opacity=\"0.1\"/><circle cx=\"10\" cy=\"60\" r=\"0.5\" fill=\"white\" opacity=\"0.1\"/></pattern></defs><rect width=\"100\" height=\"100\" fill=\"url(%23grain)\"/></svg>') repeat;\n        pointer-events: none;\n    }\n}\n\n.hero-content {\n    position: relative;\n    z-index: 3;\n    transition: transform 0.1s ease-out;\n}\n\n.floating-element {\n    position: absolute;\n    opacity: 0.4;\n    animation: float 6s ease-in-out infinite;\n    z-index: 2;\n\n    &:nth-child(1) { \n        top: 20%; \n        left: 10%; \n        animation-delay: 0s; \n    }\n    \n    &:nth-child(2) { \n        top: 60%; \n        left: 80%; \n        animation-delay: 2s; \n    }\n    \n    &:nth-child(3) { \n        top: 30%; \n        right: 15%; \n        animation-delay: 4s; \n    }\n}\n\n// Puzzle Layer Animations (for decorative elements)\n.puzzle-layer {\n    position: absolute;\n    width: 100%;\n    height: 100%;\n    border-radius: 20px;\n    background: linear-gradient(135deg, var(--primary-color), #ff6b6b, #4ecdc4);\n    opacity: 0.8;\n    transition: all 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);\n    cursor: pointer;\n\n    &:nth-child(1) {\n        background: linear-gradient(135deg, #f9a743 0%, transparent 100%);\n        z-index: 3;\n        animation: rotateLayer1 10s linear infinite;\n    }\n\n    &:nth-child(2) {\n        background: linear-gradient(135deg, transparent 0%, #ff6b6b 50%, transparent 100%);\n        z-index: 2;\n        animation: rotateLayer2 15s linear infinite reverse;\n    }\n\n    &:nth-child(3) {\n        background: linear-gradient(135deg, #4ecdc4 0%, transparent 100%);\n        z-index: 1;\n        animation: rotateLayer3 20s linear infinite;\n    }\n}","// Features Section Styles\n.whosfor-section {\n    padding: 100px 0;\n    background: linear-gradient(to bottom, #ffffff 0%, #f8f9fa 100%);\n    position: relative;\n    z-index: 10;\n}\n\n.features-section {\n    padding: 100px 0;\n    background: linear-gradient(to bottom, #f8f9fa 0%, #ffffff 100%);\n    position: relative;\n    z-index: 10;\n}\n\n.unique-features-section {\n    padding: 100px 0;\n    background: linear-gradient(to bottom, #ffffff 0%, #f8f9fa 100%);\n    position: relative;\n    z-index: 10;\n}\n\n.feature-showcase {\n    position: relative;\n    transition: transform 0.3s ease;\n\n    &:hover {\n        transform: translateY(-10px);\n    }\n}\n\n.showcase-image {\n    img {\n        max-width: 100%;\n        height: auto;\n        object-fit: cover;\n    }\n}\n\n.feature-content {\n    padding: 2rem 0;\n}\n\n// Partners Section\n.partners-section {\n    padding: 80px 0;\n    background: linear-gradient(to bottom, #f8f9fa 0%, #ffffff 100%);\n    position: relative;\n    z-index: 10;\n}\n\n// Video Section\n.video-section {\n    padding: 100px 0;\n    background: var(--text-primary);\n    color: white;\n    position: relative;\n    z-index: 10;\n}\n\n.video-container {\n    position: relative;\n    border-radius: 20px;\n    overflow: hidden;\n    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.3);\n    transition: transform 0.3s ease;\n\n    &:hover {\n        transform: scale(1.02);\n    }\n}","// Testimonials Section\n.testimonials-section {\n    padding: 100px 0;\n    background: var(--stakco-dark-deep-rosewood);\n    color: white;\n    position: relative;\n    z-index: 10;\n}","// Contact Section\n.contact-section {\n    padding: 100px 0;\n    background: var(--text-primary);\n    color: white;\n    position: relative;\n    z-index: 10;\n}\n\n.contact-form {\n    background: var(--glass-bg);\n    backdrop-filter: blur(20px);\n    border-radius: 20px;\n    padding: 2rem;\n    border: 1px solid var(--glass-border);\n}","// Footer Styles\n.footer-block {\n    background: var(--stakco-light-champagne-horizon);\n}\n\n.footer-modern {\n    background: var(--stakco-dark-wine-gold);\n    color: white;\n    position: relative;\n    overflow: hidden;\n\n    &::before {\n        content: '';\n        position: absolute;\n        top: 0;\n        left: 0;\n        right: 0;\n        bottom: 0;\n        background: url('data:image/svg+xml,<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\"><defs><pattern id=\"footer-grain\" width=\"100\" height=\"100\" patternUnits=\"userSpaceOnUse\"><circle cx=\"25\" cy=\"25\" r=\"1\" fill=\"white\" opacity=\"0.05\"/><circle cx=\"75\" cy=\"75\" r=\"1\" fill=\"white\" opacity=\"0.05\"/><circle cx=\"50\" cy=\"10\" r=\"0.5\" fill=\"white\" opacity=\"0.05\"/></pattern></defs><rect width=\"100\" height=\"100\" fill=\"url(%23footer-grain)\"/></svg>') repeat;\n        pointer-events: none;\n    }\n}\n\n.footer-content {\n    position: relative;\n    z-index: 2;\n    padding: 4rem 0 2rem;\n}\n\n.footer-main {\n    padding-bottom: 3rem;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n    margin-bottom: 2rem;\n}\n\n.footer-logo {\n    margin-bottom: 2rem;\n\n    img {\n        filter: brightness(0) invert(1);\n        transition: all 0.3s ease;\n    }\n\n    &:hover img {\n        filter: brightness(0) invert(1) drop-shadow(0 0 10px rgba(249, 167, 67, 0.5));\n        transform: scale(1.05);\n    }\n}\n\n.footer-description {\n    font-size: 1.1rem;\n    line-height: 1.6;\n    opacity: 0.9;\n    margin-bottom: 2rem;\n    max-width: 600px;\n    margin-left: auto;\n    margin-right: auto;\n}\n\n.footer-links {\n    display: flex;\n    justify-content: center;\n    gap: 3rem;\n    margin-bottom: 2rem;\n    flex-wrap: wrap;\n}\n\n.footer-link-group {\n    h5 {\n        color: var(--primary-color);\n        font-weight: 600;\n        margin-bottom: 1rem;\n        font-size: 1rem;\n    }\n\n    ul {\n        list-style: none;\n        padding: 0;\n        margin: 0;\n    }\n\n    li {\n        margin-bottom: 0.5rem;\n    }\n\n    a {\n        color: rgba(255, 255, 255, 0.8);\n        text-decoration: none;\n        transition: all 0.3s ease;\n        font-size: 0.95rem;\n        display: inline-flex;\n        align-items: center;\n        gap: 0.5rem;\n\n        &:hover {\n            color: var(--primary-color);\n            transform: translateX(5px);\n        }\n\n        i {\n            font-size: 0.8rem;\n            opacity: 0.7;\n        }\n    }\n}\n\n.footer-social {\n    display: flex;\n    justify-content: center;\n    gap: 1rem;\n    margin-bottom: 2rem;\n}\n\n.social-link {\n    width: 45px;\n    height: 45px;\n    background: rgba(255, 255, 255, 0.1);\n    backdrop-filter: blur(10px);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: white;\n    text-decoration: none;\n    transition: all 0.3s ease;\n    font-size: 1.1rem;\n\n    &:hover {\n        background: var(--primary-gradient);\n        color: white;\n        transform: translateY(-3px);\n        box-shadow: 0 5px 15px rgba(249, 167, 67, 0.4);\n    }\n}\n\n.footer-bottom {\n    text-align: center;\n}\n\n.footer-bottom-content {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 1rem;\n}\n\n.footer-legal {\n    display: flex;\n    gap: 2rem;\n    align-items: center;\n    flex-wrap: wrap;\n\n    a {\n        color: rgba(255, 255, 255, 0.7);\n        text-decoration: none;\n        font-size: 0.9rem;\n        transition: all 0.3s ease;\n\n        &:hover {\n            color: var(--primary-color);\n        }\n    }\n\n    .separator {\n        color: rgba(255, 255, 255, 0.3);\n        font-size: 0.8rem;\n    }\n}\n\n.footer-copyright {\n    color: rgba(255, 255, 255, 0.6);\n    font-size: 0.85rem;\n    margin: 0;\n}\n\n.footer-patent {\n    background: rgba(249, 167, 67, 0.1);\n    border: 1px solid rgba(249, 167, 67, 0.2);\n    border-radius: 20px;\n    padding: 0.5rem 1rem;\n    font-size: 0.8rem;\n    color: var(--primary-color);\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    margin-top: 1rem;\n}","// Animation Keyframes and Utilities\n\n// Floating animation for hero elements\n@keyframes float {\n    0%, 100% { \n        transform: translateY(0px) rotate(0deg); \n    }\n    50% { \n        transform: translateY(-20px) rotate(5deg); \n    }\n}\n\n// Rotation animations for puzzle layers\n@keyframes rotateLayer1 {\n    from { transform: rotate(0deg); }\n    to { transform: rotate(360deg); }\n}\n\n@keyframes rotateLayer2 {\n    from { transform: rotate(0deg); }\n    to { transform: rotate(360deg); }\n}\n\n@keyframes rotateLayer3 {\n    from { transform: rotate(0deg); }\n    to { transform: rotate(360deg); }\n}\n\n// Image stack rotation animation\n@keyframes rotate {\n    from { transform: rotate(0deg); }\n    to { transform: rotate(360deg); }\n}\n\n// Loading spinner animation\n@keyframes spin {\n    0% { transform: rotate(0deg); }\n    100% { transform: rotate(360deg); }\n}\n\n// Loading overlay styles\n.loading-overlay {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    background: var(--text-primary);\n    z-index: 10000;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: opacity 0.5s ease;\n}\n\n.loading-spinner {\n    width: 60px;\n    height: 60px;\n    border: 4px solid rgba(249, 167, 68, 0.3);\n    border-top: 4px solid var(--primary-color);\n    border-radius: 50%;\n    animation: spin 1s linear infinite;\n}\n\n// Fade-in animation utilities\n.fade-in {\n    opacity: 0;\n    transform: translateY(30px);\n    transition: all 0.8s ease;\n\n    &.visible {\n        opacity: 1;\n        transform: translateY(0);\n    }\n}\n\n// Performance optimization for low-end devices\n.low-performance {\n    .floating-element { \n        animation: none; \n    }\n    \n    .puzzle-layer { \n        animation-duration: 20s; \n    }\n}","// Responsive Design Utilities\n\n// Mobile breakpoint adjustments\n@media (max-width: 768px) {\n    .hero-section h1 {\n        font-size: 2.5rem;\n    }\n    \n    .feature-card, \n    .whosfor-card {\n        margin-bottom: 2rem;\n    }\n    \n    .unique-features-section .row {\n        margin-bottom: 3rem;\n    }\n    \n    .feature-content {\n        padding: 1rem 0;\n    }\n\n    // Footer responsive adjustments\n    .footer-content {\n        padding: 3rem 0 1.5rem;\n    }\n    \n    .footer-links {\n        flex-direction: column;\n        gap: 2rem;\n        text-align: center;\n    }\n    \n    .footer-bottom-content {\n        flex-direction: column;\n        text-align: center;\n    }\n    \n    .footer-legal {\n        justify-content: center;\n        order: 2;\n    }\n    \n    .footer-copyright {\n        order: 1;\n        margin-bottom: 1rem;\n    }\n}\n\n@media (max-width: 576px) {\n    .footer-links {\n        gap: 1.5rem;\n    }\n    \n    .footer-legal {\n        flex-direction: column;\n        gap: 1rem;\n\n        .separator {\n            display: none;\n        }\n    }\n}\n\n// Base typography for responsive design\n.display-5 {\n    @media (max-width: 768px) {\n        font-size: 2rem;\n    }\n}\n\n.display-6 {\n    @media (max-width: 768px) {\n        font-size: 1.75rem;\n    }\n}\n\n.lead {\n    @media (max-width: 768px) {\n        font-size: 1rem;\n    }\n}"]}